const input = $input.first().json;
const body = input.body ?? input;

const changes = body.changes || [];
let diffText = '';
for (const c of changes) {
  diffText += `\n### ${c.new_path || c.old_path}\n`;
  diffText += (c.diff || '').slice(0, 12000);
}
if (!diffText.trim()) {
  diffText = '(無 diff 內容)';
}

const prompt = `你是資深 Code Reviewer。請審核以下 GitLab Merge Request 變更。\n\n專案: ${body.projectName}\nMR: !${body.mrIid} - ${body.title}\n作者: ${body.authorName || 'unknown'}\n\n請用繁體中文回覆，並嚴格輸出 JSON（不要 markdown code fence）：\n{\n  "summary": "一句話摘要",\n  "suggestions": "Markdown 條列建議",\n  "fullReview": "完整審核說明",\n  "severity": 1-5 整數\n}\n\n--- DIFF ---\n${diffText}`;

return [{
  json: {
    reviewId: body.reviewId,
    callbackUrl: body.callbackUrl,
    projectName: body.projectName,
    mrIid: body.mrIid,
    prompt
  }
}];

